        score = 0.0

        # Resource attraction
        if nearest_res is not None:
            old = abs(nearest_res[0] - me[0]) + abs(nearest_res[1] - me[1])
            new = abs(nearest_res[0] - nx) + abs(nearest_res[1] - ny)
            score += (old - new) * 3.0

        # Enemy avoidance
        if nearest_enemy is not None:
            old = abs(nearest_enemy[0] - me[0]) + abs(nearest_enemy[1] - me[1])
            new = abs(nearest_enemy[0] - nx) + abs(nearest_enemy[1] - ny)
            score += (new - old) * (4.0 + 2.0 * threat_weight)

        # Spread from all enemies a bit
        for e in enemies[:8]:
            old = abs(e[0] - me[0]) + abs(e[1] - me[1])
            new = abs(e[0] - nx) + abs(e[1] - ny)
            score += 0.25 * (new - old)

        # Mild preference for center when no clear target
        if width is not None and height is not None:
            oldc = abs(center[0] - me[0]) + abs(center[1] - me[1])
            newc = abs(center[0] - nx) + abs(center[1] - ny)
            score += 0.15 * (oldc - newc)

        # Avoid stacking with allies if visible
        for a in allies[:8]:
            if a[0] == nx and a[1] == ny:
                score -= 0.5

        # Slight inertia to stay put if already good
        if dx == 0 and dy == 0:
            score += 0.05

        if best_score is None or score > best_score:
            best_score = score
            best_move = [dx, dy]

    return [clamp(best_move[0]), clamp(best_move[1])]

